window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1f0c75a4c05387f"]={"versions": [{"id": "FIG-c1f0c75a4c05387f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens bei der BusOff-Behandlung innerhalb des AUTOSAR Classic Platform Communication Stacks (Can-Treiber, CanIf und obere Schichten/Nutzer-Callbacks).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>«interface» CanIf_User_Cbk</code>: Callback-Schnittstelle zu übergeordneten Schichten (z. B. CanSM).</li>\n<li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.</li>\n<li><code>«module» Can</code>: AUTOSAR CAN Driver Modul (gekennzeichnet mit Unendlich-Symbol für asynchrone/wiederholende Verarbeitung).</li>\n<li><code>«Peripheral» CanController</code>: Hardwarenaher CAN-Controller.</li>\n</ul>\n<p class=\"fig-p\">Aufrufe und Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\">\n<li><code>BusOff Detection()</code></li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code></li>\n<li><code>CanIf_ControllerBusOff(uint8)</code></li>\n<li><code>Change to CANIF_CS_STOPPED()</code></li>\n<li><code>Reset transmit queue()</code></li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8)</code></li>\n<li>Rückgabesignale: <code>&lt;User_ControllerBusOff&gt;()</code>, <code>CanIf_ControllerBusOff()</code>, <code>BusOff Detection()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>CanController</code> erkennt einen BusOff-Zustand (<code>BusOff Detection()</code>) und meldet diesen an das Modul <code>Can</code>.</li>\n<li>Das Modul <code>Can</code> setzt den Controller bei Bedarf in den Modus STOPPED (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), bestätigt durch die Hardware.</li>\n<li>Das Modul <code>Can</code> ruft <code>CanIf_ControllerBusOff(uint8)</code> auf dem <code>CanIf</code> auf (unter Übergabe der Controller-ID).</li>\n<li><code>CanIf</code> führt interne Zustandsübergänge durch:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechselt den Zustand auf <code>CANIF_CS_STOPPED</code> (<code>Change to CANIF_CS_STOPPED()</code>).</li>\n<li>Setzt die Sendewarteschlangen zurück (<code>Reset transmit queue()</code>), annotiert mit dem Kommentar: „Transmit queues being reset to avoid transmission of old L-PDUs after CAN controller restart“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>CanIf</code> leitet das Ereignis über <code>&lt;User_ControllerBusOff&gt;(uint8)</code> an den konfigurierten Callback-Empfänger (<code>CanIf_User_Cbk</code>) weiter.</li>\n<li>Die Aufrufkette kehrt synchron zurück (<code>&lt;User_ControllerBusOff&gt;()</code> -> <code>CanIf_ControllerBusOff()</code> -> <code>BusOff Detection()</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zurücksetzen der Transmit-Queues (<code>Reset transmit queue()</code>) stellt sicher, dass nach einem BusOff und anschließendem Neustart des CAN-Controllers keine veralteten L-PDUs übertragen werden.</li>\n<li>Die Benachrichtigung der oberen Schicht (<code>&lt;User_ControllerBusOff&gt;</code>) muss den betroffenen CAN-Controller via <code>uint8</code>-Parameter identifizieren.</li>\n<li>Der Wechsel in <code>CANIF_CS_STOPPED</code> muss im <code>CanIf</code> vor dem Verarbeiten weiterer Anfragen oder dem Abschluss des Callbacks erfolgen.</li>\n</ul>"}, {"id": "FIG-6b0d19472d711d30", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens bei der BusOff-Behandlung innerhalb des AUTOSAR Classic Platform Communication Stacks (Can-Treiber, CanIf und obere Schichten/Nutzer-Callbacks).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>«interface» CanIf_User_Cbk</code>: Callback-Schnittstelle zu übergeordneten Schichten (z. B. CanSM).</li>\n<li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.</li>\n<li><code>«module» Can</code>: AUTOSAR CAN Driver Modul (gekennzeichnet mit Unendlich-Symbol für asynchrone/wiederholende Verarbeitung).</li>\n<li><code>«Peripheral» CanController</code>: Hardwarenaher CAN-Controller.</li>\n</ul>\n<p class=\"fig-p\">Aufrufe und Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\">\n<li><code>BusOff Detection()</code></li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code></li>\n<li><code>CanIf_ControllerBusOff(uint8)</code></li>\n<li><code>Change to CANIF_CS_STOPPED()</code></li>\n<li><code>Reset transmit queue()</code></li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8)</code></li>\n<li>Rückgabesignale: <code>&lt;User_ControllerBusOff&gt;()</code>, <code>CanIf_ControllerBusOff()</code>, <code>BusOff Detection()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>CanController</code> erkennt einen BusOff-Zustand (<code>BusOff Detection()</code>) und meldet diesen an das Modul <code>Can</code>.</li>\n<li>Das Modul <code>Can</code> setzt den Controller bei Bedarf in den Modus STOPPED (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), bestätigt durch die Hardware.</li>\n<li>Das Modul <code>Can</code> ruft <code>CanIf_ControllerBusOff(uint8)</code> auf dem <code>CanIf</code> auf (unter Übergabe der Controller-ID).</li>\n<li><code>CanIf</code> führt interne Zustandsübergänge durch:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechselt den Zustand auf <code>CANIF_CS_STOPPED</code> (<code>Change to CANIF_CS_STOPPED()</code>).</li>\n<li>Setzt die Sendewarteschlangen zurück (<code>Reset transmit queue()</code>), annotiert mit dem Kommentar: „Transmit queues being reset to avoid transmission of old L-PDUs after CAN controller restart“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>CanIf</code> leitet das Ereignis über <code>&lt;User_ControllerBusOff&gt;(uint8)</code> an den konfigurierten Callback-Empfänger (<code>CanIf_User_Cbk</code>) weiter.</li>\n<li>Die Aufrufkette kehrt synchron zurück (<code>&lt;User_ControllerBusOff&gt;()</code> -> <code>CanIf_ControllerBusOff()</code> -> <code>BusOff Detection()</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Zurücksetzen der Transmit-Queues (<code>Reset transmit queue()</code>) stellt sicher, dass nach einem BusOff und anschließendem Neustart des CAN-Controllers keine veralteten L-PDUs übertragen werden.</li>\n<li>Die Benachrichtigung der oberen Schicht (<code>&lt;User_ControllerBusOff&gt;</code>) muss den betroffenen CAN-Controller via <code>uint8</code>-Parameter identifizieren.</li>\n<li>Der Wechsel in <code>CANIF_CS_STOPPED</code> muss im <code>CanIf</code> vor dem Verarbeiten weiterer Anfragen oder dem Abschluss des Callbacks erfolgen.</li>\n</ul>"}], "trans": [{"from": "FIG-c1f0c75a4c05387f", "to": "FIG-6b0d19472d711d30", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
